func (c *Core) cdltasukigapOpenAndFillInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32, outBegIdx, outNBElement *int32, outInteger []int32) (*CDLTASUKIGAPStream, error) {
	sp := &CDLTASUKIGAPStream{core: c}
	if retCode := c.cdltasukigapOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, outBegIdx, outNBElement, outInteger, 1); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(*outBegIdx)
	sp.outRangeCount = int(*outNBElement)
	return sp, nil
}

func (c *Core) cdltasukigapOpenInternal(inOpen, inHigh, inLow, inClose []float64, startIdx int32) (*CDLTASUKIGAPStream, error) {
	sp := &CDLTASUKIGAPStream{core: c}
	var outBegIdx, outNBElement int32
	var sink_outInteger [1]int32
	if retCode := c.cdltasukigapOpenSinkFrame(sp, inOpen, inHigh, inLow, inClose, startIdx, &outBegIdx, &outNBElement, sink_outInteger[:]); retCode != Success {
		return nil, retCode
	}
	sp.outRangeBegIdx = int(outBegIdx)
	sp.outRangeCount = int(outNBElement)
	return sp, nil
}

// CDLTASUKIGAPOpen opens a live [CDLTASUKIGAPStream] on a warm-up history,
// oldest bar first, and returns it with its value at the last history bar, the
// value [Core.CDLTASUKIGAP] writes there.
//
// inOpen, inHigh, inLow and inClose are the histories, of one length.
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CDLTASUKIGAPLookback] bars, [OutOfRangeEndIndex] for one longer than
// [IndexMax]+1 bars, and [BadParam] for histories of different lengths.
func (c *Core) CDLTASUKIGAPOpen(inOpen, inHigh, inLow, inClose []float64) (*CDLTASUKIGAPStream, int32, error) {
	sp, err := c.cdltasukigapOpenInternal(inOpen, inHigh, inLow, inClose, 0)
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outInteger, nil
}

// CDLTASUKIGAPOpenAndFill opens a stream as [Core.CDLTASUKIGAPOpen] does and
// also writes the outputs over the whole history, as [Core.CDLTASUKIGAP] writes
// them for bars 0 through len(inOpen)-1, returning that range.
//
// Each output must hold len(inOpen) minus [Core.CDLTASUKIGAPLookback] values
// and share no memory with an input or another output.
//
// The errors are those of [Core.CDLTASUKIGAPOpen], and [BadParam] for an output
// that is empty, too short or sharing memory.
func (c *Core) CDLTASUKIGAPOpenAndFill(inOpen, inHigh, inLow, inClose []float64, outInteger []int32) (*CDLTASUKIGAPStream, OutRange, error) {
	if len(inOpen) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cdltasukigapLookback())
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	if len(inHigh) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inLow) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	if len(inClose) != len(inOpen) {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inOpen)-lookback, 0)
	if len(outInteger) == 0 || len(outInteger) < outLen {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cdltasukigapOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, &outBegIdx, &outNBElement, outInteger)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
